// Watercolour wash helper — creates soft bleed edges
const WC = {
  // Soft watercolour filter definition
  filter: (id) => (
    <defs>
      <filter id={id} x="-20%" y="-20%" width="140%" height="140%">
        <feTurbulence type="fractalNoise" baseFrequency="0.04" numOctaves="3" result="noise"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="2" xChannelSelector="R" yChannelSelector="G" result="displaced"/>
        <feGaussianBlur in="displaced" stdDeviation="0.4" result="blurred"/>
        <feBlend in="SourceGraphic" in2="blurred" mode="multiply"/>
      </filter>
    </defs>
  ),
};

