// ── Goal → yoga mapping ───────────────────────────────────────
function getYogaForGoal(goals, phase) {
  const goalMap = {
    "lose weight": ["weightloss","strength","flexibility"],
    "weight loss": ["weightloss","strength","flexibility"],
    "gain weight": ["weightgain","strength","flexibility"],
    "gain muscle": ["weightgain","strength","balance"],
    "muscle": ["weightgain","strength","balance"],
    "digestion": ["digestion","flexibility","sleep"],
    "gut": ["digestion","flexibility","sleep"],
    "gas": ["digestion","flexibility"],
    "bloating": ["digestion","flexibility"],
    "sleep": ["sleep","flexibility","eyes"],
    "stress": ["sleep","flexibility","womens"],
    "anxiety": ["sleep","flexibility","digestion"],
    "back pain": ["backpain","flexibility","strength"],
    "posture": ["backpain","strength","balance"],
    "eyes": ["eyes","sleep","flexibility"],
    "eye": ["eyes","sleep"],
    "balance": ["balance","strength","flexibility"],
    "flexibility": ["flexibility","balance","sleep"],
    "women": ["womens","flexibility","sleep"],
    "hormonal": ["womens","flexibility","sleep"],
    "period": ["womens","digestion","sleep"],
    "menstrual": ["womens","digestion","sleep"],
    "pcos": ["womens","strength","digestion"],
    "energy": ["weightloss","strength","flexibility"],
    "stamina": ["weightloss","strength","balance"],
  };
  const matched = new Set();
  const goalLower = (goals || "").toLowerCase();
  for (const [keyword, cats] of Object.entries(goalMap)) {
    if (goalLower.includes(keyword)) cats.forEach(c => matched.add(c));
  }
  if (matched.size === 0) matched.add("flexibility");
  if (phase && ["menstrual","pms","luteal"].includes(phase)) matched.add("womens");
  return [...matched].slice(0, 4);
}

