// Calculate Mahadasha from birth nakshatra
function calcMahadasha(nakIdx, dob) {
  const nak = NAKSHATRAS_V[nakIdx];
  const lord = nak.lord;
  const lordIdx = MAHADASHA_ORDER.indexOf(lord);
  
  // Fraction of nakshatra completed at birth (approximate)
  const fracComplete = 0.5; // simplified — real calc needs precise longitude
  
  const birthDate = new Date(dob);
  let currentDate = new Date();
  
  // Build dasha timeline starting from birth
  const dashas = [];
  let startDate = new Date(birthDate);
  
  // Adjust start based on fraction of first dasha completed
  const firstYears = MAHADASHA_YEARS[lord];
  const completedYears = firstYears * fracComplete;
  startDate.setFullYear(startDate.getFullYear() - completedYears);
  
  for (let i = 0; i < MAHADASHA_ORDER.length * 3; i++) {
    const planet = MAHADASHA_ORDER[(lordIdx + i) % MAHADASHA_ORDER.length];
    const years = MAHADASHA_YEARS[planet];
    const endDate = new Date(startDate);
    endDate.setFullYear(endDate.getFullYear() + years);
    dashas.push({ planet, start: new Date(startDate), end: new Date(endDate), years });
    startDate = new Date(endDate);
    if (startDate > new Date(birthDate.getFullYear() + 120, 0)) break;
  }
  
  // Find current dasha
  const now = new Date();
  const current = dashas.find(d => d.start <= now && d.end > now);
  const next = current ? dashas[dashas.indexOf(current) + 1] : null;
  
  return { dashas, current, next };
}

// Antardasha calculator
function calcAntardasha(mahadashaPlanet, dashaStart, dashaEnd) {
  const totalYears = MAHADASHA_YEARS[mahadashaPlanet];
  const lordIdx = MAHADASHA_ORDER.indexOf(mahadashaPlanet);
  const antardashas = [];
  let start = new Date(dashaStart);
  
  for (let i = 0; i < MAHADASHA_ORDER.length; i++) {
    const planet = MAHADASHA_ORDER[(lordIdx + i) % MAHADASHA_ORDER.length];
    const fraction = MAHADASHA_YEARS[planet] / 120;
    const durationMs = (dashaEnd - dashaStart) * fraction;
    const end = new Date(start.getTime() + durationMs);
    antardashas.push({ planet, start: new Date(start), end: new Date(end) });
    start = new Date(end);
  }
  
  const now = new Date();
  const current = antardashas.find(d => d.start <= now && d.end > now);
  return { antardashas, current };
}

// Sade Sati calculator
function calcSadeSati(moonSignIdx) {
  // Saturn takes ~2.5 years per sign, 7.5 years total for Sade Sati
  // Saturn sign positions (approximate, 2024-2035)
  // Saturn was in Aquarius (Kumbha=10) from Jan 2023 to Mar 2025
  // Saturn enters Pisces (Meena=11) Mar 2025
  // Saturn enters Aries (Mesha=0) Jun 2027
  
  const saturnTransits = [
    { sign: 9, start: new Date("2020-01-23"), end: new Date("2022-04-28"), name:"Makara" },
    { sign: 10, start: new Date("2022-04-29"), end: new Date("2025-03-28"), name:"Kumbha" },
    { sign: 11, start: new Date("2025-03-29"), end: new Date("2027-08-25"), name:"Meena" },
    { sign: 0, start: new Date("2027-08-26"), end: new Date("2029-10-19"), name:"Mesha" },
    { sign: 1, start: new Date("2029-10-20"), end: new Date("2032-01-20"), name:"Vrishabha" },
  ];
  
  const moonSign = moonSignIdx; // 0-11
  const prev = ((moonSign - 1) + 12) % 12;
  const next = (moonSign + 1) % 12;
  const sadeSatiSigns = [prev, moonSign, next];
  
  const now = new Date();
  
  // Check current Saturn position
  const currentSaturn = saturnTransits.find(t => t.start <= now && t.end >= now);
  const isSadeSati = currentSaturn && sadeSatiSigns.includes(currentSaturn.sign);
  
  // Find full Sade Sati period
  const ssTransits = saturnTransits.filter(t => sadeSatiSigns.includes(t.sign));
  
  let phase = null;
  if (isSadeSati && currentSaturn) {
    if (currentSaturn.sign === prev) phase = "Rising (1st phase) — Career and finances face pressure";
    if (currentSaturn.sign === moonSign) phase = "Peak (2nd phase) — Most intense. Health, relationships, identity challenged.";
    if (currentSaturn.sign === next) phase = "Setting (3rd phase) — Gradual relief. Lessons integrating.";
  }
  
  // Next Sade Sati
  const futureSS = saturnTransits.find(t => sadeSatiSigns.includes(t.sign) && t.start > now);
  
  // Check for Dhaiya (2.5 year Saturn transit over 4th or 8th from moon)
  const dhaiyaSigns = [(moonSign + 3) % 12, (moonSign + 7) % 12];
  const isDhaiya = currentSaturn && dhaiyaSigns.includes(currentSaturn.sign);
  
  return { isSadeSati, isDhaiya, phase, currentSaturn, ssTransits, futureSS, sadeSatiSigns, moonSign };
}

// Dosha calculator
function calcDoshas(lagna, moon, sun, birthTime) {
  const doshas = [];
  
  // Mangal Dosha — Mars in 1st, 2nd, 4th, 7th, 8th, 12th from lagna
  // Simplified: check based on lagna sign
  // Scorpio lagna — Mars is the ruling planet — Mangal Dosha is often neutralised
  const isManglikLagna = [0, 3, 6, 7, 10, 11].includes(lagna); // approximate
  const isManglikCancelled = lagna === 7 || lagna === 0; // Scorpio/Aries lagna often cancels
  
  doshas.push({
    name: "Mangal Dosha",
    icon: "♂",
    color: "#e05a5a",
    present: isManglikLagna && !isManglikCancelled,
    severity: isManglikLagna && !isManglikCancelled ? "Moderate" : "Absent/Cancelled",
    explanation: isManglikCancelled
      ? "Your Scorpio Lagna is ruled by Mars itself, which significantly neutralises Mangal Dosha. Many astrologers consider this a complete cancellation."
      : isManglikLagna
      ? "Mars placement suggests some Mangal Dosha influence. However, multiple cancellation factors need to be checked."
      : "Mangal Dosha does not appear strongly in your chart.",
    effects: isManglikLagna && !isManglikCancelled
      ? ["Delays in marriage possible","Relationship intensity can be high","Partner may also need to be Manglik for balance"]
      : ["No significant Mangal Dosha effects","Marriage partnerships are generally supported"],
    remedies: ["Kumbh Vivah ritual if strongly Manglik","Worship Hanuman on Tuesdays","Wear red coral after consulting astrologer","Fast on Tuesdays"],
    cancellations: ["Scorpio or Aries Lagna — Mars is own sign, neutralises","Mangal Dosha of both partners — cancels each other","Mars in its own nakshatra"],
  });
  
  // Kaal Sarp Dosha — Rahu-Ketu axis with all planets between them
  // This requires full planetary positions — providing interpretation based on Rahu Mahadasha
  doshas.push({
    name: "Kaal Sarp Dosha",
    icon: "🐍",
    color: "#9060b0",
    present: false, // Cannot determine without full chart — being honest
    severity: "Needs full chart verification",
    explanation: "Kaal Sarp Dosha occurs when all 7 planets fall between Rahu and Ketu. This requires your complete planetary positions to verify accurately. Your Rahu Mahadasha currently active means Rahu's energy is strongly influencing your life regardless.",
    effects: ["If present: obstacles and delays in early life, then sudden breakthroughs","Rahu Mahadasha brings Rahu's karmic themes to the forefront"],
    remedies: ["Worship Nag Devta on Nag Panchami","Rudrabhishek on Mondays","Mahamrityunjaya Japa 108 times daily","Visit Trimbakeshwar or Srikalahasti temples"],
    cancellations: ["Jupiter aspecting Rahu or Ketu neutralises","Own sign Rahu or Ketu","Many planets on one side only"],
  });
  
  // Pitra Dosha
  doshas.push({
    name: "Pitra Dosha",
    icon: "🙏",
    color: "#7090a8",
    present: false,
    severity: "Needs Sun-Rahu conjunction check",
    explanation: "Pitra Dosha is associated with Sun-Rahu conjunction or Sun in Rahu's nakshatra. Your Pisces Sun in Rahu Mahadasha means ancestral karma is an active theme. Performing Pitru Tarpan (especially on Amavasya) is beneficial regardless.",
    effects: ["Ancestral karma influences current life","Recurring patterns from family lineage","Health of father/paternal line"],
    remedies: ["Pitru Tarpan on every Amavasya","Feed crows on Saturdays","Donate to Brahmins/priests on father's behalf","Gaya pilgrimage for Pind Daan"],
    cancellations: [],
  });
  
  return doshas;
}

// ── Format date helper ─────────────────────────────────────────
function fmtDate(d) {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-IN", { day:"numeric", month:"long", year:"numeric" });
}
function fmtDateShort(d) {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-IN", { month:"short", year:"numeric" });
}

